def IsOneUnconditional (b : UnconditionalSchauderBasis ℕ 𝕜 E) : Prop :=
  ∀ (s : Finset ℕ) (θ : ℕ → 𝕜), (∀ i, ‖θ i‖ ≤ 1) →
    ∀ x : E, ‖∑ i ∈ s, (θ i * b.coord i x) • b i‖ ≤ ‖x‖

